import json
grid = [list(map(int, r.split())) for r in inp.split("\n")]
R, C = len(grid), len(grid[0])
shape = 3
cells = [(r,c) for r in range(R) for c in range(C) if grid[r][c]==shape]
r0,r1 = min(r for r,c in cells), max(r for r,c in cells)
c0,c1 = min(c for r,c in cells), max(c for r,c in cells)

# column dash counts within bbox
colcount = {c: sum(1 for r in range(r0,r1+1) if grid[r][c]==shape) for c in range(c0,c1+1)}
vlines = {c0, c1} | {c for c in range(c0,c1+1) if colcount[c] >= 4}
bars = set()
for r in range(r0,r1+1):
    if any(grid[r][c]==shape and c not in vlines for c in range(c0,c1+1)):
        bars.add(r)
out = [row[:] for row in grid]
for r in range(r0,r1+1):
    for c in range(c0,c1+1):
        if grid[r][c] == 1 and (r in bars or c in vlines):
            out[r][c] = 2
print("vlines:", sorted(vlines), "bars:", sorted(bars))
for r in range(r0,r1+1):
    print(r, out[r][c0:c1+1])
json.dump(out, open("submit.json","w"))
